// CV-qualified type variants (all distinct types):
int x;                    // cv-unqualified
const int cx;             // const-qualified
volatile int vx;          // volatile-qualified
const volatile int cvx;   // const-volatile-qualified

// Compound types: cv-qualifiers don't propagate
const int* p1;            // Pointer to const int (pointer is mutable)
int* const p2;            // Const pointer to int (pointee is mutable)
const int* const p3;      // Const pointer to const int

// Array cv-qualification applies to elements
typedef int IntArray[10];
const IntArray arr;       // Same as: const int arr[10]
int const arr2[10];       // Same as above

// Partial ordering (for conversions):
int* -> const int*              // OK: less cv-qualified to more
const int* -> int*              // ERROR: more cv-qualified to less
volatile int* -> const volatile int*  // OK: ordering rule

code_example:
#include <iostream>
#include <type_traits>

// Demonstrate cv-qualified types are distinct
template<typename T>
void show_type_info(const char* name) {
    std::cout << name << ": size=" << sizeof(T) 
              << ", const=" << std::is_const<T>::value
              << ", volatile=" << std::is_volatile<T>::value << "\n";
}

class Widget {
public:
    int value;
    mutable int cache;  // mutable: can modify even in const object

    void regular() { std::cout << "Non-const member\n"; }
    void read_only() const { 
        // value = 10;  // ERROR: can't modify in const member
        cache = 20;     // OK: mutable subobject
        std::cout << "Const member\n"; 
    }
};

int main() {
    std::cout << "=== CV-Qualifiers: Distinct Types, Same Size ===\n\n";

    // 1. Distinct types with same representation
    show_type_info<int>("int");
    show_type_info<const int>("const int");
    show_type_info<volatile int>("volatile int");
    show_type_info<const volatile int>("const volatile int");

    // 2. Compound types: cv-qualifiers don't propagate
    std::cout << "\n=== Compound Types ===\n";
    int x = 10;
    const int cx = 20;

    const int* p1 = &cx;     // Pointer to const (pointer is mutable)
    p1 = &x;                 // OK: reassign pointer
    // *p1 = 30;             // ERROR: can't modify through const pointer

    int* const p2 = &x;      // Const pointer (pointee is mutable)
    *p2 = 30;                // OK: modify pointee
    // p2 = &cx;             // ERROR: can't reassign const pointer

    std::cout << "Pointer to const: can reassign pointer\n";
    std::cout << "Const pointer: can modify pointee\n";

    // 3. Array cv-qualification applies to elements
    std::cout << "\n=== Array CV-Qualification ===\n";
    typedef int IntArray[5];
    const IntArray arr1 = {1, 2, 3, 4, 5};  // const int arr1[5]
    int const arr2[5] = {1, 2, 3, 4, 5};    // Same type

    // Both are arrays of const int
    std::cout << "arr1 is const: " 
              << std::is_const<std::remove_extent<decltype(arr1)>::type>::value << "\n";
    // arr1[0] = 10;  // ERROR: elements are const

    // 4. Const objects and mutable subobjects
    std::cout << "\n=== Const Objects and Mutable ===\n";
    const Widget w{42, 0};
    // w.value = 100;     // ERROR: w is const object
    w.cache = 999;        // OK: mutable subobject
    w.read_only();        // OK: const member function
    // w.regular();       // ERROR: non-const member on const object

    std::cout << "Mutable subobject modified: " << w.cache << "\n";

    // 5. Partial ordering (compile-time check)
    std::cout << "\n=== Partial Ordering ===\n";
    std::cout << "int convertible to const int: "
              << std::is_convertible<int*, const int*>::value << "\n";
    std::cout << "const int convertible to int: "
              << std::is_convertible<const int*, int*>::value << "\n";
    std::cout << "volatile convertible to const volatile: "
              << std::is_convertible<volatile int*, const volatile int*>::value << "\n";

    return 0;
}

// Output:
// === CV-Qualifiers: Distinct Types, Same Size ===
//
// int: size=4, const=0, volatile=0
// const int: size=4, const=1, volatile=0
// volatile int: size=4, const=0, volatile=1
// const volatile int: size=4, const=1, volatile=1
//
// === Compound Types ===
// Pointer to const: can reassign pointer
// Const pointer: can modify pointee
//
// === Array CV-Qualification ===
// arr1 is const: 1
//
// === Const Objects and Mutable ===
// Const member
// Mutable subobject modified: 999
//
// === Partial Ordering ===
// int convertible to const int: 1
// const int convertible to int: 0
// volatile convertible to const volatile: 1
